import { installDom } from './dom.js';
import { installStorage } from './storage.js';
import { installStoreState } from './state.js';
import { installFocus } from './focus.js';
import { installBlindSpots } from './blind-spots.js';
import { installDownload } from './download.js';
import { installContextOpen } from './context-open.js';
import { installNetwork } from './network.js';
import { installIpc, ipcNetOverrides, isReticleOwnIpc } from './ipc.js';
import { installPerf } from './perf.js';
import { installRoute } from './route.js';
import { installNavigation } from './navigation.js';
import { installDeparture } from './departure.js';
import { installConsole } from './console.js';
import { installDialogs } from './dialogs.js';
import { installAnimation } from './animation.js';
import { installScroll } from './scroll.js';
import { installHealth } from './health.js';
import { reportSdkFailure, SdkSite } from './sdk-failure.js';
function guard(emit, site, install) {
    try {
        return install();
    }
    catch (error) {
        reportSdkFailure(emit, site, error);
        return () => { };
    }
}
export function runTeardowns(emit, teardowns) {
    for (const teardown of teardowns) {
        try {
            teardown();
        }
        catch (error) {
            reportSdkFailure(emit, SdkSite.TEARDOWN, error);
        }
    }
}
export function installAllObservers(emit, options) {
    return [
        guard(emit, SdkSite.NETWORK_OBSERVER, () => installNetwork(emit, {
            captureBodies: options.captureBodies,
            ...(options.captureErrorBodies === undefined
                ? {}
                : { captureErrorBodies: options.captureErrorBodies }),
            reinterpret: ipcNetOverrides,
            ignore: isReticleOwnIpc,
        })),
        guard(emit, SdkSite.IPC_OBSERVER, () => installIpc(emit, { captureBodies: options.captureBodies })),
        guard(emit, SdkSite.ANIMATION_OBSERVER, () => installPerf(emit)),
        guard(emit, SdkSite.ROUTER_OBSERVER, () => installRoute(emit)),
        guard(emit, SdkSite.NETWORK_OBSERVER, () => installNavigation(emit)),
        guard(emit, SdkSite.NETWORK_OBSERVER, () => installDeparture(emit)),
        guard(emit, SdkSite.CONSOLE_OBSERVER, () => installConsole(emit)),
        guard(emit, SdkSite.CONSOLE_OBSERVER, () => installDialogs(emit)),
        guard(emit, SdkSite.ANIMATION_OBSERVER, () => installAnimation(emit)),
        guard(emit, SdkSite.DOM_OBSERVER, () => installScroll(emit)),
        guard(emit, SdkSite.DOM_OBSERVER, () => installDom(emit)),
        guard(emit, SdkSite.STORE_ADAPTER, () => installStorage(emit)),
        guard(emit, SdkSite.STORE_ADAPTER, () => installStoreState(emit)),
        guard(emit, SdkSite.DOM_OBSERVER, () => installFocus(emit)),
        guard(emit, SdkSite.NETWORK_OBSERVER, () => installDownload(emit, { capturePreview: options.captureBodies })),
        guard(emit, SdkSite.DOM_OBSERVER, () => installBlindSpots(emit)),
        guard(emit, SdkSite.HEALTH_OBSERVER, () => installHealth(emit)),
        guard(emit, SdkSite.DOM_OBSERVER, () => installContextOpen(emit)),
    ];
}
