import { EventType } from '@reticlehq/core';
import { captureMethod } from '../patching/capture-method.js';
import { observeSafely } from './types.js';
export function installContextOpen(emit) {
    const originalOpen = captureMethod(window, 'open');
    if (originalOpen === undefined)
        return () => { };
    const openPatch = function (href, target, features) {
        const opened = originalOpen.call(this, href, target, features);
        observeSafely(() => {
            emit(EventType.CONTEXT_OPENED, { ...(href === undefined ? {} : { href }) });
        });
        return opened;
    };
    const patchedOpen = openPatch;
    window.open = patchedOpen;
    return () => {
        if (window.open === patchedOpen)
            window.open = originalOpen;
    };
}
