import { EventType, NetInitiator } from '@reticlehq/core';
import { observeSafely } from './types.js';
const NON_NAVIGATING = /^(javascript|mailto|tel|sms|blob|data):/i;
function anchorFor(target) {
    if (!(target instanceof Element))
        return undefined;
    const anchor = target.closest('a');
    return anchor instanceof HTMLAnchorElement ? anchor : undefined;
}
export function isDeparture(href, downloadAttr, here) {
    if (0 === href.length || NON_NAVIGATING.test(href))
        return false;
    if (downloadAttr)
        return true;
    try {
        const target = new URL(href, here);
        const current = new URL(here);
        if (target.origin === current.origin) {
            return target.pathname !== current.pathname || target.search !== current.search;
        }
        return true;
    }
    catch {
        return false;
    }
}
export function installDeparture(emit) {
    if ('undefined' === typeof document)
        return () => undefined;
    let seq = 0;
    const onClick = (event) => {
        observeSafely(() => {
            const anchor = anchorFor(event.target);
            if (anchor === undefined)
                return;
            const href = anchor.getAttribute('href') ?? '';
            const here = document.location.href;
            const download = anchor.hasAttribute('download');
            if (!isDeparture(href, download, here))
                return;
            const url = new URL(href, here).toString();
            queueMicrotask(() => {
                observeSafely(() => {
                    if (event.defaultPrevented)
                        return;
                    seq += 1;
                    emit(EventType.NET_PENDING, {
                        id: `nav-${String(seq)}`,
                        method: 'GET',
                        url,
                        initiator: NetInitiator.NAVIGATION,
                        ...(download ? { download: true } : {}),
                    });
                });
            });
        });
    };
    document.addEventListener('click', onClick, true);
    return () => document.removeEventListener('click', onClick, true);
}
