import { EventType } from '@reticlehq/core';
import { captureMethod } from '../patching/capture-method.js';
import { projectBody } from './net-detail/network-body.js';
import { observeSafely, observeValue } from './types.js';
const TEXTUAL = /text\/|json|csv|xml|ndjson|javascript/i;
const PREVIEW_CHARS = 2000;
export function installDownload(emit, opts = {}) {
    if (typeof URL.createObjectURL !== 'function')
        return () => undefined;
    const objectUrl = URL.createObjectURL.bind(URL);
    const known = new Map();
    const originalCreate = captureMethod(URL, 'createObjectURL');
    const patchedCreate = function reticleObservedObjectUrl(obj) {
        const url = objectUrl(obj);
        observeSafely(() => {
            if (typeof Blob !== 'undefined' && obj instanceof Blob) {
                const text = TEXTUAL.test(obj.type)
                    ? obj.text().catch(() => undefined)
                    : Promise.resolve(undefined);
                known.set(url, { type: obj.type, size: obj.size, text });
            }
        });
        return url;
    };
    URL.createObjectURL = patchedCreate;
    const report = (url, filename) => {
        const record = known.get(url);
        if (record === undefined)
            return;
        known.delete(url);
        void record.text.then((text) => {
            observeSafely(() => {
                emitDownload(record, filename, text);
            });
        });
    };
    const emitDownload = (record, filename, text) => {
        const data = { mimeType: record.type, bytes: record.size };
        if (filename !== undefined && filename.length > 0)
            data['filename'] = filename;
        if (text !== undefined) {
            data['lines'] = text.split('\n').filter((l) => l.length > 0).length;
            if (true === opts.capturePreview) {
                const { body, truncated } = projectBody(text.slice(0, PREVIEW_CHARS), record.type);
                data['preview'] = body;
                if (truncated)
                    data['previewTruncated'] = true;
            }
        }
        emit(EventType.DOWNLOAD, data);
    };
    const onClick = (event) => {
        observeSafely(() => {
            const target = event.target;
            const anchor = target instanceof Element ? target.closest('a[download]') : null;
            if (null === anchor)
                return;
            report(anchor.getAttribute('href') ?? '', anchor.getAttribute('download') ?? undefined);
        });
    };
    document.addEventListener('click', onClick, true);
    const originalClick = captureMethod(HTMLAnchorElement.prototype, 'click');
    const patchedClick = function reticleObservedAnchorClick() {
        const pending = observeValue(() => this.hasAttribute('download')
            ? {
                href: this.getAttribute('href') ?? '',
                name: this.getAttribute('download') ?? undefined,
            }
            : undefined);
        originalClick.call(this);
        observeSafely(() => {
            if (pending !== undefined)
                report(pending.href, pending.name);
        });
    };
    HTMLAnchorElement.prototype.click = patchedClick;
    return () => {
        document.removeEventListener('click', onClick, true);
        if (URL.createObjectURL === patchedCreate)
            URL.createObjectURL = originalCreate;
        if (HTMLAnchorElement.prototype.click === patchedClick) {
            HTMLAnchorElement.prototype.click = originalClick;
        }
        known.clear();
    };
}
