export function createCommitAggregator(options) {
    let pending = 0;
    let scheduled = false;
    return {
        onCommit() {
            pending += 1;
            if (scheduled)
                return;
            scheduled = true;
            options.schedule(() => {
                scheduled = false;
                const commits = pending;
                pending = 0;
                if (commits > 0)
                    options.flush(commits);
            });
        },
    };
}
